mapper.insert:
INSERT INTO merchant_shipping_rates (merchant_id, country_code, state_province, fee)
VALUES (#{merchantId}, '', '', #{fee})
ON DUPLICATE KEY UPDATE fee = #{fee}

mapper.update:
UPDATE merchant_shipping_rates
SET country_code = #{rate.countryCode}, state_province = #{rate.stateProvince}, fee = #{rate.fee}
WHERE merchant_id = #{merchantId} AND country_code = #{countryCode} AND state_province = #{stateProvince}

UPDATE merchant_shipping_rates
SET enabled = #{enabled}
WHERE merchant_id = #{merchantId} AND country_code = #{countryCode} AND state_province = #{stateProvince}

mapper.select:
SELECT scope_hash, order_id
FROM checkout_receipts
WHERE customer_id = #{customerId} AND quote_id = #{quoteId}
